    -- Back-pressure on cfg01 only (Phase 3 regression: stall then recover)
    p_bp01 : process
    begin
        c01_mready(0) <= '0';
        c01_mready(C01_NUM_TAPS-1 downto 1) <= (others => '1');
        wait until c01_rst = '0';
        wait for CLK_PERIOD * 10;
        c01_mready(0) <= '1';
        wait;
    end process p_bp01;

    -- Stimulus processes

    p_stim01 : process
        file     f   : text;
        variable ln  : line;
        variable pv  : integer;
        variable col : natural range 0 to 8-1;
        variable row : natural range 0 to 8-1;
    begin
        wait for CLK_PERIOD * 5;
        wait until rising_edge(clk);
        c01_rst <= '0';
        file_open(f, C01_IN_FILE, read_mode);
        col := 0;  row := 0;
        while not endfile(f) loop
            readline(f, ln);  read(ln, pv);
            c01_sdata  <= std_logic_vector(to_unsigned(pv, C01_DW));
            c01_svalid <= '1';
            if row = 0 and col = 0 then c01_suser <= '1'; else c01_suser <= '0'; end if;
            if col = C_LW-1 then c01_slast <= '1'; else c01_slast <= '0'; end if;
            wait until rising_edge(clk) and c01_sready = '1';
            if col = C_LW-1 then
                col := 0;
                if row = C_FH-1 then row := 0; else row := row+1; end if;
            else
                col := col+1;
            end if;
        end loop;
        c01_svalid <= '0';  c01_slast <= '0';  c01_suser <= '0';
        file_close(f);
        wait;
    end process p_stim01;

    p_stim02 : process
        file     f   : text;
        variable ln  : line;
        variable pv  : integer;
        variable col : natural range 0 to 8-1;
        variable row : natural range 0 to 8-1;
    begin
        wait for CLK_PERIOD * 5;
        wait until rising_edge(clk);
        c02_rst <= '0';
        file_open(f, C02_IN_FILE, read_mode);
        col := 0;  row := 0;
        while not endfile(f) loop
            readline(f, ln);  read(ln, pv);
            c02_sdata  <= std_logic_vector(to_unsigned(pv, C02_DW));
            c02_svalid <= '1';
            if row = 0 and col = 0 then c02_suser <= '1'; else c02_suser <= '0'; end if;
            if col = C_LW-1 then c02_slast <= '1'; else c02_slast <= '0'; end if;
            wait until rising_edge(clk) and c02_sready = '1';
            if col = C_LW-1 then
                col := 0;
                if row = C_FH-1 then row := 0; else row := row+1; end if;
            else
                col := col+1;
            end if;
        end loop;
        c02_svalid <= '0';  c02_slast <= '0';  c02_suser <= '0';
        file_close(f);
        wait;
    end process p_stim02;

    p_stim03 : process
        file     f   : text;
        variable ln  : line;
        variable pv  : integer;
        variable col : natural range 0 to 8-1;
        variable row : natural range 0 to 8-1;
    begin
